-- Migration 0011_billing_webhook: generated by drizzle-kit (the column), function hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #204)
-- Razorpay webhook pipeline (#28 part 5):
--   * billing_event.payload (nullable jsonb) stores the minimised webhook event (no contact data)
--     that the `billing.process-event` job applies; job payloads carry ids only.
--   * app_billing_workspace_for_provider_subscription(provider, id) maps a stored provider
--     subscription id to its workspace. The webhook has no workspace and `subscription` is under
--     FORCE row-level security, so it resolves through this owner-defined SECURITY DEFINER
--     function (reading via owner_definer_read from 0007). It returns the workspace id only, and
--     never trusts payload metadata.
--   * Additive only; the previous release never reads the column or calls the function.
ALTER TABLE "billing_event" ADD COLUMN "payload" jsonb;--> statement-breakpoint
CREATE FUNCTION app_billing_workspace_for_provider_subscription(
  p_provider text, p_provider_subscription_id text
)
  RETURNS uuid
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    SELECT s.workspace_id FROM subscription s
    WHERE s.provider = p_provider AND s.provider_subscription_id = p_provider_subscription_id
    ORDER BY s.created_at DESC
    LIMIT 1
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_billing_workspace_for_provider_subscription(text, text) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_billing_workspace_for_provider_subscription(text, text) TO causedeck_app;
